            }
            else
            {
                // Si ya había EditContext pero el modelo cambió (nuevo objeto), reconfigurarlo
                UpdateEditContextIfNeeded();
            }

            if (initialized)
            {
                await InvokeAsync(StateHasChanged);
            }
        }
    }

